with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('blive nødt til', 'phrase', 'a8501ff7-9ffb-57f1-ad5f-3b53c24617ae', 1, 'verb', null, 'бути змушеним', 'Jeg bliver nødt til at gå nu.', 'Мені треба йти.'), ('gå over', 'phrase', '8e36bd6d-9177-527e-9777-b42a8b150af5', 1, 'verb', null, 'проходити (про біль, неприємне відчуття)', 'Hovedpinen gik over efter en times søvn.', 'Головний біль минув після години сну.'), ('gå over', 'phrase', '41acbae6-5d83-5025-a501-bdcf6cbc5db8', 2, 'verb', null, 'переходити (з одного стану в інший)', 'Regnen gik over i slud i løbet af natten.', 'Дощ змінився на мокрий сніг уночі.'), ('løbe tør', 'phrase', 'eef777d1-b8bc-52d1-b027-a323978dcc6b', 1, 'verb', null, 'закінчуватися (про запаси)', 'Mælken løb tør i morges.', 'Молоко закінчилося сьогодні вранці.'), ('komme ud', 'phrase', '8d3df9a3-4aa9-528c-a5a8-89178e795db5', 1, 'verb', null, 'виходити (назовні)', 'Jeg kommer ud i haven hver morgen.', 'Я щоранку виходжу в сад.'), ('køre på', 'phrase', 'de2ffd5b-89ed-5f93-bd85-e1a1de76cede', 1, 'verb', null, 'їхати (на чомусь)', 'Han kører på cykel hver dag.', 'Він щодня їздить на велосипеді.'), ('køre til', 'phrase', '1177c608-4ac0-51a3-ac5a-8fc3a6d49d8c', 1, 'verb', null, 'їхати (машиною) до (місця)', 'Vi kører til stranden hver sommer.', 'Ми їздимо на пляж щоліта.'), ('trænge til', 'phrase', 'ddebd350-9958-5815-816b-b498bc413107', 1, 'verb', null, 'потребувати чогось', 'Jeg trænger til en kop kaffe.', 'Мені потрібна чашка кави.'), ('sige ja', 'phrase', 'aeffb308-e3cf-58a6-9992-0bb8a01d534c', 1, 'verb', null, 'погоджуватися', 'Hun sagde ja til invitationen.', 'Вона прийняла запрошення.'), ('stille sig', 'phrase', '89a3aee3-aca9-5b7f-9e33-dfb907137a2e', 1, 'verb', null, 'прикидатися (якимось)', 'Han stillede sig uvidende om situationen.', 'Він прикинувся, що не знає про ситуацію.'), ('skrive med', 'phrase', '5b04d74f-5914-5234-bc1b-921997e0ca97', 1, 'verb', null, 'листуватися', 'Jeg skriver med min ven hver uge.', 'Я листуюся з другом щотижня.'), ('snakke om', 'phrase', '3a7cbefa-2ea2-5a6f-b15d-907a5b6b559a', 1, 'verb', null, 'говорити про (щось)', 'De snakker om vejret hver dag.', 'Вони щодня говорять про погоду.'), ('gå op', 'phrase', '418dd95b-d9f3-52b7-bb48-40a2d2b2ec4d', 1, 'verb', null, 'підніматися (вгору)', 'Vi gik op ad trappen til anden sal.', 'Ми піднялися сходами на другий поверх.'), ('høre om', 'phrase', '3f7c21eb-e7b0-5cc3-a2f0-c9116c0393bf', 1, 'verb', null, 'чути про (щось)', 'Jeg hørte om ulykken i radioen.', 'Я чув про аварію по радіо.'), ('regne med at', 'phrase', '3dd84e8f-1d2a-59e7-93c1-0e71765a3d6f', 1, 'verb', null, 'очікувати, що', 'Jeg regner med at komme til festen i morgen.', 'Я очікую, що прийду на вечірку завтра.'), ('ligge med', 'phrase', '25caa864-3af4-5b92-a759-25c51220422b', 1, 'verb', null, 'спати з кимось', 'Hun har ligget med ham i flere måneder.', 'Вона спала з ним кілька місяців.'), ('falde af', 'phrase', 'b4a3a59c-7c4b-5295-8fea-85a47db22e07', 1, 'verb', null, 'відпадати', 'Knappen faldt af min jakke i går.', 'Вчора з мого піджака відірвався ґудзик.'), ('løbe efter', 'phrase', 'a54cf3cb-deb7-55ac-96d4-8215cc9f627a', 1, 'verb', null, 'бігти за (переслідувати)', 'Hunden løb efter katten i haven.', 'Собака побіг за котом у саду.'), ('løbe efter', 'phrase', '57ceb591-1588-5fde-becf-0cae617dc827', 2, 'verb', null, 'бігти за (принести)', 'Jeg løber efter en ekstra stol til gæsten.', 'Я збігаю за додатковим стільцем для гостя.'), ('gemme sig bag', 'phrase', '0a0bd4c9-7f62-5de2-8375-b68991bda7fc', 1, 'verb', null, 'ховатися за', 'Børnene gemmer sig bag sofaen, når de leger.', 'Діти ховаються за диваном, коли граються.'), ('tale for', 'phrase', 'e6aa4c13-e012-5e07-9572-a5410d3ba3b2', 1, 'verb', null, 'говорити на користь (чогось)', 'Hun taler for mere motion i hverdagen.', 'Вона виступає за більше фізичних вправ у повсякденному житті.'), ('være stille', 'phrase', 'c3676774-767e-5868-a36d-65b0326afed5', 1, 'verb', null, 'бути тихим (не шуміти)', 'Børnene er stille i klassen.', 'Діти тихі на уроці.'), ('tage hjem', 'phrase', '038cc85d-482b-5355-bc0f-4707978f3f31', 1, 'verb', null, 'йти додому', 'Jeg tager hjem efter arbejde.', 'Я йду додому після роботи.'), ('stoppe med', 'phrase', '9a389b69-609f-52f7-8d07-5080ff8f46ab', 1, 'verb', null, 'кидати (заняття)', 'Han stoppede med at ryge sidste år.', 'Він кинув курити минулого року.'), ('ville sige', 'phrase', '430397ad-218a-5c75-9031-b1f6bd37b335', 1, 'verb', null, 'означати', 'Det vil sige, at vi skal mødes klokken otte.', 'Це означає, що ми маємо зустрітися о восьмій.'), ('leve i', 'phrase', '2893159c-1e36-52ab-a2e1-195ef2194de0', 1, 'verb', null, 'жити в (місці, стані)', 'De lever i en lille lejlighed.', 'Вони живуть у маленькій квартирі.'), ('deltage i', 'phrase', '5967d476-a62e-5d2a-9e94-8391466afba7', 1, 'verb', null, 'брати участь у', 'Mange børn deltager i sport efter skole.', 'Багато дітей беруть участь у спортивних заняттях після школи.'), ('bryde ud', 'phrase', '8eb32750-e1cf-50ee-947a-87b685443212', 1, 'verb', null, 'вибухати (сміхом, плачем, оплесками)', 'Publikum brød ud i vild jubel.', 'Публіка вибухнула бурхливими радісними вигуками.'), ('bryde ud', 'phrase', 'dbae0736-63fa-5cf2-a9b9-67b0b0ce5e1e', 2, 'verb', null, 'спалахувати (про війну, пожежу, епідемію)', 'En voldsom brand brød ud i bygningen.', 'У будівлі спалахнула сильна пожежа.'), ('træde på', 'phrase', '216feaa2-949f-5931-81df-18a70975d2f6', 1, 'verb', null, 'наступати (ногою)', 'Han trådte på min fod i bussen.', 'Він наступив мені на ногу в автобусі.'), ('være ligeglad', 'phrase', '1951316e-fe68-544f-a816-d7d0d4c31d9e', 1, 'verb', null, 'бути байдужим', 'Jeg er ligeglad med vejret i morgen.', 'Мені байдуже, яка завтра буде погода.'), ('tage ud', 'phrase', '63b6553c-fde3-55b5-9f70-a1ec2bdf8242', 1, 'verb', null, 'вирушати (за місто, на природу)', 'Vi tager ud til stranden i morgen.', 'Завтра ми їдемо на пляж.'), ('være i live', 'phrase', '0d46ded9-749b-57d1-b1f7-6c058dc568cf', 1, 'verb', null, 'бути живим', 'Min bedstemor er i live og bor alene.', 'Моя бабуся жива і живе сама.'), ('i morgen aften', 'phrase', '35b97b83-96df-5e59-870b-38e3bda0b157', 1, 'adverb', null, 'завтра ввечері', 'Vi skal i biografen i morgen aften.', 'Завтра ввечері ми йдемо в кіно.'), ('træde ind i', 'phrase', '04cc6776-fefe-58e6-aca4-3042cba3ec48', 1, 'verb', null, 'вступати до (організації, посади)', 'Han trådte ind i hæren sidste år.', 'Він вступив до армії минулого року.'), ('kæmpe for', 'phrase', '8f655e73-707e-5e41-aa2c-e7ff90f0112b', 1, 'verb', null, 'боротися за', 'De kæmper for bedre vilkår på arbejdspladsen.', 'Вони борються за кращі умови на робочому місці.'), ('komme til skade', 'phrase', '670c2b2b-78c3-5ca8-8747-f1066d6e1c70', 1, 'verb', null, 'отримати травму', 'Han kom til skade under fodboldkampen.', 'Він отримав травму під час футбольного матчу.'), ('bekymre sig om', 'phrase', '332b171f-a95f-562a-b8fa-8e04c5ad77a6', 1, 'verb', null, 'турбуватися про', 'Hun bekymrer sig om sin søns helbred.', 'Вона хвилюється за здоров''я сина.'), ('tænde for', 'phrase', '9dd421c5-8fd8-5343-8d12-f4e6e28f9103', 1, 'verb', null, 'вмикати', 'Hun tænder for lyset i stuen.', 'Вона вмикає світло у вітальні.'), ('være vant til at', 'phrase', '791bd4ea-563b-5333-bb52-7c041f66debc', 1, 'verb', null, 'звикнути (робити щось)', 'Jeg er vant til at stå tidligt op.', 'Я звик рано вставати.'), ('sige farvel', 'phrase', '2ba23467-7681-5c50-8b69-e4b5ae15e603', 1, 'verb', null, 'прощатися', 'Hun sagde farvel til sin veninde ved toget.', 'Вона попрощалася зі своєю подругою біля поїзда.'), ('more sig', 'phrase', '69bf105d-0a9f-55d5-926a-cdef2015755b', 1, 'verb', null, 'розважатися, веселитися', 'Børnene morer sig i haven hele dagen.', 'Діти весело проводять час у саду цілий день.'), ('tage af sted', 'phrase', '2f00ac56-f26a-5c0d-a4d1-9c165032abee', 1, 'verb', null, 'вирушати (в дорогу)', 'Vi tager af sted tidligt om morgenen.', 'Вирушаємо рано вранці.'), ('sætte sig på', 'phrase', '5ec9da46-35c6-5883-bf81-5f17bc068750', 1, 'verb', null, 'сідати (на щось)', 'Hun sætter sig på stolen hver morgen.', 'Вона сідає на стілець щоранку.'), ('sætte sig på', 'phrase', 'ab68f4ac-faae-500a-911f-5ce81f22d20e', 2, 'verb', null, 'брати під контроль', 'De satte sig på hele markedet sidste år.', 'Минулого року вони захопили весь ринок.'), ('lade som om', 'phrase', 'eb2879bb-510d-5405-bfdb-230d8d330918', 1, 'verb', null, 'прикидатися', 'Hun lader som om hun sover.', 'Вона прикидається, що спить.'), ('være vild med', 'phrase', '40658091-35c1-5174-8ef8-4532a80f2cad', 1, 'verb', null, 'дуже любити (щось)', 'Jeg er vild med den nye restaurant på hjørnet.', 'Мені дуже подобається новий ресторан на розі.'), ('tvinge sig til at', 'phrase', '8e5067da-a6c6-5e95-90d6-68b0c89ceaba', 1, 'verb', null, 'змушувати себе (робити щось)', 'Jeg tvang mig til at smile, selvom jeg var ked af det.', 'Я змусив себе посміхнутися, хоч і був сумний.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0002' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
